window.LD=window.LD||{};window.LD["party/p1"]={"id":"p1","name":"The Scarlet Thorns","poss":"The Scarlet Thorns'","members":["h6","h9"],"leader":"h9","morale":99,"disposition":"wary","motto":"We are already gone.","banner":{"c1":"#c8323c","c2":"#2f9e9e","emblem":"tree"},"loc":"bleakmarsh","loc_name":"Bleakmarsh","goal":{"text":"to see the world: 6 different places before the season ends","kind":"world","done":85,"progress":"6 places","missed":false,"crew":"The Scarlet Thorns","party":"p1"},"vows":[{"text":"never to leave a companion behind","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Scarlet Thorns","party":"p1"},{"text":"to repay The Coin of Thornwall","day":34,"state":"unfinished","ended":90,"through":false,"progress":"unfinished on day 30 of season 3","crew":"The Scarlet Thorns","party":"p1"}],"doing":"last seen heading home to Ashfen","progress":null,"today":["Came away with a fish.","Ate 2 rations."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":null,"renown":162,"season":{"wins":13,"bosses":0,"floors":2,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":5},"career":{"wins":40,"bosses":0,"floors":5,"gold":0,"deaths":0,"fled":3,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":10},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"ox_wagon","name":"The Ark","label":"ox wagon","seats":5,"haul":70,"comfort":0,"since":78,"desc":"Slow as a wedding, carries a house.","moves":true,"puller":{"kind":"ox","name":"Dobbin","label":"ox","colour":"black","owner":null},"paid":[["Tobias",64]]},"pace_gap":0,"rels":[{"party":"p6","score":100},{"party":"p7","score":46},{"party":"p4","score":45},{"party":"p5","score":37},{"party":"p3","score":15},{"party":"p2","score":2}],"events":[{"id":"e27","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Tobias and Gorm shake on it at The Damp Lantern: they are now The Scarlet Thorns. (Wary, by the look of them.)","heroes":["h6","h9"],"parties":["p1"],"loc":"ashfen"},{"id":"e520","day":14,"season":1,"sday":14,"kind":"goal_done","imp":4,"text":"PILGRIMAGE: at Saltmarrow, Gorm finally looks the sea in the eye. It blinks first. Gorm is not afraid of deep water any more. It was Gorm's idea in the first place. XP: Tobias +800 (level 10!), Gorm +800 (level 11!).","heroes":["h6","h9"],"parties":["p1"],"loc":"saltmarrow","xp":{"h6":800,"h9":800}},{"id":"e752","day":20,"season":1,"sday":20,"kind":"ability","imp":2,"text":"Bandits wait in the ditch on the road to Bleakmarsh. One of them leans on a stick that Gorm put there. A net drops, a bell rings, and the ambush is over.","heroes":["h9"],"parties":["p1"],"loc":"bleakmarsh","skill":"every_path_rigged","sk":"Every Path Rigged","rule":true},{"id":"e754","day":20,"season":1,"sday":20,"kind":"talent","imp":1,"text":"Gorm circles the camp at dusk with a coil of wire. Tobias learns to step high on the way to bed. Every Path Rigged: one of the things Gorm learned the long way round.","heroes":["h9","h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"every_path_rigged"},{"id":"e755","day":20,"season":1,"sday":20,"kind":"night","imp":2,"text":"A child turns up at The Scarlet Thorns' camp in Bleakmarsh, announces that Goblin Camp \"eats lanterns\", and runs off before anyone can ask what that means.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh"},{"id":"e784","day":21,"season":1,"sday":21,"kind":"fight","imp":3,"text":"The Scarlet Thorns run for it in Bleakmarsh, routed by 2 Swamp Trolls and a Bog Crawler. Tobias hasn't said a word since. Gorm has to be dragged out. Injured: Gorm (broken arm).","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f61","foes":["bog_crawler","swamp_troll","swamp_troll"],"where":"in Bleakmarsh","won":false,"close":true,"shape":"plain","reworded":7},{"id":"e829","day":22,"season":1,"sday":22,"kind":"ambush","imp":2,"text":"With Tobias hitting hardest, the Scarlet Thorns cut down a Bog Crawler on the road to Ashfen. Tobias' Thorn Whip put poison in the bog crawler, and it did its slow work. Gorm never once gave ground.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f69","foes":["bog_crawler"],"where":"on the road to Ashfen","won":true,"close":false,"shape":"hero","reworded":-29},{"id":"e1048","day":27,"season":1,"sday":27,"kind":"fight","imp":2,"text":"In Bleakmarsh again, for the third time in ten days: the Scarlet Thorns make short work of 3 Giant Spiders. The last giant spider breaks and runs. After Tobias' Caltrops, the giant spider hit like a tired farmhand. Ambush did more for this fight than the scoreboard shows. That was Tobias. Loot: 6 chitin, a giant spider leg.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f84","foes":["giant_spider","giant_spider","giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"again","reworded":-49},{"id":"e1049","day":27,"season":1,"sday":27,"kind":"fight","imp":3,"text":"It's 2 Will-o'-Wisps against the Scarlet Thorns in Bleakmarsh, and it isn't close. Everyone fought a little better after Tobias' Ambush. Gorm did the unglamorous work that kept the line from breaking. Loot: 5 bottled wisplight.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f85","foes":["wisp","wisp"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"foe","reworded":-26},{"id":"e1068","day":27,"season":1,"sday":27,"kind":"meet","imp":2,"text":"The Green Arrows warn The Scarlet Thorns about what's lurking in Bleakmarsh. The Scarlet Thorns pretend to already know.","heroes":["h17","h13","h6","h9"],"parties":["p5","p1"],"loc":"bleakmarsh"},{"id":"e1069","day":27,"season":1,"sday":27,"kind":"talent","imp":2,"text":"Tobias stops at a quiet bend, frowns, and takes the long way. Later word comes of what was waiting there. Somebody asks how. 'True Pathfinder,' says Tobias.","heroes":["h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"true_pathfinder"},{"id":"e1083","day":28,"season":1,"sday":28,"kind":"fight","imp":3,"text":"The Scarlet Thorns, in fine spirits lately, dispatch a Giant Spider in Bleakmarsh. Tobias' Caltrops took the strength out of the giant spider. Gorm saw every rush coming and shouted it in time. Loot: 3 chitin.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f88","foes":["giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e1084","day":28,"season":1,"sday":28,"kind":"fight","imp":1,"text":"In Bleakmarsh, a Bog Crawler and a Giant Spider get in the Scarlet Thorns' way, briefly. That Thorn Whip from Tobias was the moment it tipped. Loot: 6 chitin.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f89","foes":["bog_crawler","giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-17},{"id":"e1103","day":28,"season":1,"sday":28,"kind":"meet","imp":1,"text":"Juniper's Shields and The Scarlet Thorns share a fire in Bleakmarsh. Isolde shares a flask.","heroes":["h10","h12","h18","h6","h9"],"parties":["p4","p1"],"loc":"bleakmarsh"},{"id":"e1146","day":29,"season":1,"sday":29,"kind":"argument","imp":3,"text":"Gorm says one thing too many about Gorm's habit of humming during ambushes. Tobias says two.","heroes":["h9","h6"],"parties":["p1"]},{"id":"e1162","day":30,"season":1,"sday":30,"kind":"road","imp":3,"text":"Tobias reports the drowned box to the local reeve rather than touching it. The reeve is moved, and Tobias's name is passed around kindly.","heroes":["h6","h9"],"parties":["p1"],"road":"bleakmarsh~carrbridge","road_rec":"r198"},{"id":"e1197","day":30,"season":1,"sday":30,"kind":"journey","imp":2,"text":"The Scarlet Thorns and The Tidal Ledger fall in together on the road to Carrbridge and spend the miles arguing about whether ghosts pay taxes.","heroes":["h6","h9","h7","h19","h2","h14"],"parties":["p1","p7"]},{"id":"e1202","day":30,"season":1,"sday":30,"kind":"argument","imp":1,"text":"Tobias and Gorm of The Scarlet Thorns have a shouting match about the ethics of looting bodies.","heroes":["h6","h9"],"parties":["p1"]},{"id":"e1249","day":31,"season":2,"sday":1,"kind":"campfire","imp":2,"text":"Tobias and Gorm see in a month of The Scarlet Thorns by splitting the last good bottle. Nobody else is offered any.","heroes":["h6","h9"],"parties":["p1"],"loc":"carrbridge"},{"id":"e1262","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"A vow from The Scarlet Thorns: never to leave a companion behind. Easy to say on day one.","heroes":["h6","h9"],"parties":["p1"]},{"id":"e1274","day":32,"season":2,"sday":2,"kind":"talent","imp":2,"text":"Gorm explains, at length, the difference between a cave and a cavern. Nobody asked. Tobias is now interested.","heroes":["h9","h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"spelunker","wx":"rain"},{"id":"e1289","day":32,"season":2,"sday":2,"kind":"campfire","imp":1,"text":"Gorm and Tobias share a rain cloak in a downpour and arrive soaked and laughing.","heroes":["h9","h6"],"parties":["p1"],"loc":"bleakmarsh","wx":"rain"},{"id":"e1294","day":33,"season":2,"sday":3,"kind":"fight","imp":2,"text":"The Scarlet Thorns make short work of a Swamp Troll and Risen Dead in Bleakmarsh without much fuss. Nobody invited the dead. They came anyway, drawn by the noise, and made it everyone's problem. Everyone fought a little better after Tobias' Ambush. Tobias's Thorn Whip did the damage (2 times). Loot: 18 silver each, 3 troll hide, 3 troll haunches.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f96","foes":["swamp_troll","zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-18,"wx":"fog"},{"id":"e1325","day":33,"season":2,"sday":3,"kind":"argument","imp":4,"text":"Gorm and Tobias have had the same argument three times now. This time Gorm just walks away mid-sentence, which is worse. The campfire now has a line down the middle.","heroes":["h9","h6"],"parties":["p1"]},{"id":"e1327","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"Gorm slips Ember a sausage under the table. Tobias sees, and decides Gorm is all right.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","wx":"fog"},{"id":"e1352","day":34,"season":2,"sday":4,"kind":"fight","imp":1,"text":"The Scarlet Thorns handle a Bog Crawler in Bleakmarsh, in the rain. Tobias' Thorn Whip took most of the fight out of the bog crawler in one go. Loot: 3 chitin, 3 bog crawler claws.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f100","foes":["bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"weather","reworded":-13,"wx":"rain"},{"id":"e1355","day":34,"season":2,"sday":4,"kind":"fight","imp":3,"text":"Two Swamp Trolls are too much for the Scarlet Thorns in Bleakmarsh, and it's time to run for it. Tobias hasn't said a word since. Gorm has to be dragged out.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f101","foes":["swamp_troll","swamp_troll"],"where":"in Bleakmarsh","won":false,"close":true,"shape":"foe","reworded":-19,"wx":"rain"},{"id":"e1356","day":34,"season":2,"sday":4,"kind":"rescue","imp":4,"text":"The Scarlet Thorns are in a bad way in Bleakmarsh when The Coin of Thornwall turns up. Brix (Griffin's hero) gets Tobias (Alex's hero) on a horse. A debt is remembered.","heroes":["h1","h6","h8","h16","h9"],"parties":["p6","p1"],"loc":"bleakmarsh","rescuers":["h1","h8","h16"],"wx":"rain"},{"id":"e1357","day":34,"season":2,"sday":4,"kind":"vow","imp":3,"text":"The Scarlet Thorns owe The Coin of Thornwall a life, and swear to repay The Coin of Thornwall. A debt is a debt.","heroes":["h6","h9"],"parties":["p1"],"cause":"e1356"},{"id":"e1360","day":34,"season":2,"sday":4,"kind":"meet","imp":2,"text":"Gorm and Duren swap stories in Bleakmarsh while The Scarlet Thorns and The Thunder of Frosthold swap rumours.","heroes":["h6","h9","h5","h3","h4","h15"],"parties":["p1","p3"],"loc":"bleakmarsh","wx":"rain"},{"id":"e1364","day":34,"season":2,"sday":4,"kind":"talent","imp":1,"text":"Tobias drills marching order on a quiet stretch. Gorm finally learns which side is left.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","skill":"drillmaster","wx":"rain"},{"id":"e1443","day":36,"season":2,"sday":6,"kind":"talent","imp":1,"text":"Tobias brews something green and bitter for Gorm's cough. Gorm hates it. The cough's gone by morning.","heroes":["h6","h9"],"parties":["p1"],"loc":"ashveil_crypts","skill":"herbalism","wx":"rain"},{"id":"e1461","day":37,"season":2,"sday":7,"kind":"delve","imp":1,"text":"The Scarlet Thorns descend into the Ashveil Crypts, untouched (0%).","heroes":["h6","h9"],"parties":["p1"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e1462","day":37,"season":2,"sday":7,"kind":"fight","imp":3,"text":"With Tobias hitting hardest, the Scarlet Thorns beat 3 Skeleton Archers and Risen Dead in the ossuary on floor 1 of the Ashveil Crypts. Tobias' Caltrops caught four of them at once. Loot: 13 bones, 3 grave dust, 3 crypt-caps.","heroes":["h6","h9"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f113","foes":["skeleton_archer","zombie","skeleton_archer"],"where":"in the ossuary on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-29,"wx":"rain"},{"id":"e1463","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"The Scarlet Thorns work floor 1 of the Ashveil Crypts at a steady pace: 3 rooms (the lych-gate, the ossuary, the gatekeeper's lodge).","heroes":["h6","h9"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":3,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["cosmetic"],"fears":1,"wild":[]},"wx":"rain"},{"id":"e1495","day":38,"season":2,"sday":8,"kind":"fight","imp":1,"text":"In the gravediggers' shed on floor 1 of the Ashveil Crypts, the Scarlet Thorns square up to 3 Giant Rats and carry the day. Frost from Gorm's Bramble Snare had the giant rat stumbling. Loot: 3 fangs & claws, a rat haunch.","heroes":["h6","h9"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f119","foes":["giant_rat","giant_rat","giant_rat"],"where":"in the gravediggers' shed on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-13,"wx":"storm"},{"id":"e1496","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"The Scarlet Thorns work floor 1 of the Ashveil Crypts at a cautious pace: 3 rooms (the gravediggers' shed, the mourners' porch, the sexton's lodging).","heroes":["h6","h9"],"parties":["p1"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e1519","day":39,"season":2,"sday":9,"kind":"fight","imp":1,"text":"The Scarlet Thorns get the better of 2 Skeletons in the gatehouse on floor 1 of the Ashveil Crypts. After Tobias' Caltrops, the skeleton hit like a tired farmhand. Loot: 12 bones, 3 crypt-caps.","heroes":["h6","h9"],"parties":["p1"],"loc":"ashveil_crypts","fight":"f120","foes":["skeleton","skeleton"],"where":"in the gatehouse on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"plain","reworded":-13,"wx":"storm"},{"id":"e1520","day":39,"season":2,"sday":9,"kind":"gear","imp":1,"text":"In a sealed space off the gatehouse on floor 1 of the Ashveil Crypts, Gorm finds a Keen Brass Lantern, and stashes it to sell. Keen: a steadier aim (+2 aim).","heroes":["h9"],"parties":["p1"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1521","day":39,"season":2,"sday":9,"kind":"delve_day","imp":1,"text":"The Scarlet Thorns work floor 1 of the Ashveil Crypts at a steady pace: 2 rooms (the gatehouse, a sealed space off the gatehouse).","heroes":["h6","h9"],"parties":["p1"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great"],"fears":0,"wild":[]},"wx":"storm"},{"id":"e1546","day":40,"season":2,"sday":10,"kind":"delve_done","imp":3,"text":"The daylight is a shock after 4 days, and The Scarlet Thorns come out into it shading every eye. They reached floor 1, worked through 8 rooms, found the ossuary, the gatekeeper's lodge and a sealed space off the gatehouse, put 23% of it on paper, split 62 silver on the way up and turned back because they were down to the last torch. Between every crew so far, the Ashveil Crypts is mostly unexplored (10%).","heroes":["h6","h9"],"parties":["p1"],"loc":"ashveil_crypts","days":4,"bottom":false,"rooms":["the ossuary","the gatekeeper's lodge"],"gold":62,"turn":"dark","wx":"storm"},{"id":"e1636","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"The Scarlet Thorns' plan for the season, as told to the barkeep: to earn 250 silver between them before the season ends.","heroes":["h6","h9"],"parties":["p1"]},{"id":"e1669","day":42,"season":2,"sday":12,"kind":"goal_progress","imp":2,"text":"The Scarlet Thorns are getting close: earn 250 silver between them before the season ends (160 of 250 silver).","heroes":["h6","h9"],"parties":["p1"]},{"id":"e1677","day":43,"season":2,"sday":13,"kind":"road","imp":3,"text":"Tobias follows the trail of a bishop's hat through a turnip field and finds the Archbishop asleep in a haystack, entirely at peace.","heroes":["h6","h9"],"parties":["p1"],"road":"carrbridge~ironhaven","traveller":"mumchance","road_rec":"r272"},{"id":"e1689","day":43,"season":2,"sday":13,"kind":"talent","imp":2,"text":"Tobias draws a better map of the region on an Ironhaven tavern table than the one on the wall.","heroes":["h6"],"parties":["p1"],"loc":"ironhaven","skill":"true_pathfinder","wx":"heat"},{"id":"e1697","day":43,"season":2,"sday":13,"kind":"campfire","imp":2,"text":"Tobias admits to being afraid of being forgotten. Gorm doesn't laugh. Gorm just nods and takes the watch nearest it.","heroes":["h9","h6"],"parties":["p1"],"loc":"ironhaven","wx":"heat"},{"id":"e1726","day":44,"season":2,"sday":14,"kind":"road","imp":3,"text":"'None shall cross!' cries Sir Aldous Puddle, who adds, a little quieter, 'unless they've time for a bout.' Gorm has.","heroes":["h9","h6"],"parties":["p1"],"road":"ironhaven~redcrag","traveller":"aldous","road_rec":"r283"},{"id":"e1761","day":45,"season":2,"sday":15,"kind":"fight","imp":2,"text":"Win number four in a row: the Scarlet Thorns make short work of 2 Drakes in Redcrag Hills. The last drake takes off and isn't seen again. The drake was already dying of Tobias' Thorn Whip before it knew it. Loot: 4 fangs & claws, 3 drake flanks.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag","fight":"f132","foes":["drake","drake"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"streak","reworded":-51,"wx":"fog"},{"id":"e1770","day":45,"season":2,"sday":15,"kind":"ability","imp":2,"text":"Tobias reads the crows circling over the next wood, says 'not today', and turns aside. Whatever was waiting in there waits for somebody else, and the party sleeps easy.","heroes":["h6"],"parties":["p1"],"loc":"redcrag","skill":"true_pathfinder","sk":"True Pathfinder","rule":true,"wx":"fog"},{"id":"e1859","day":47,"season":2,"sday":17,"kind":"journey","imp":2,"text":"The Scarlet Thorns and The Tidal Ledger fall in together on the road to Carrbridge and spend the miles arguing about the best way to cook a rat.","heroes":["h6","h9","h7","h19","h2","h14"],"parties":["p1","p7"]},{"id":"e1869","day":47,"season":2,"sday":17,"kind":"goal_done","imp":4,"text":"GOAL: The Scarlet Thorns set out to earn 250 silver between them before the season ends, and they have done it, with 13 days to spare. It was Tobias's idea in the first place. XP: Tobias +960 (level 16!), Gorm +960 (level 16!).","heroes":["h6","h9"],"parties":["p1"],"xp":{"h6":960,"h9":960}},{"id":"e1924","day":50,"season":2,"sday":20,"kind":"fight","imp":1,"text":"In Bleakmarsh, Risen Dead gets in the Scarlet Thorns' way, briefly. Tobias ended it with Poisoned Blade. Tobias's Ambush kicked in when it counted. Loot: 4 grave dust.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f142","foes":["zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-16,"wx":"fog"},{"id":"e1947","day":50,"season":2,"sday":20,"kind":"ability","imp":2,"text":"Tobias hears a bridge creak wrong, walks the long way round, and is proven right by a loud splash behind her. It is not her splash.","heroes":["h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"true_pathfinder","sk":"True Pathfinder","rule":true,"wx":"fog"},{"id":"e1969","day":51,"season":2,"sday":21,"kind":"fight","imp":1,"text":"Two Giant Spiders fall to the Scarlet Thorns in Bleakmarsh. That Deadfall from Gorm was the moment it tipped. Loot: 4 chitin, 3 spider legs.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f145","foes":["giant_spider","giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"foe","reworded":-2,"wx":"fog"},{"id":"e1984","day":51,"season":2,"sday":21,"kind":"talent","imp":2,"text":"Gorm catches a fox in a road snare, apologises to it and lets it go. Every Path Rigged, the guild calls it.","heroes":["h9"],"parties":["p1"],"loc":"bleakmarsh","skill":"every_path_rigged","wx":"fog"},{"id":"e2023","day":52,"season":2,"sday":22,"kind":"talent","imp":1,"text":"Tobias knows which Ashfen warehouse door to knock on, and how many times.","heroes":["h6"],"parties":["p1"],"loc":"ashfen","skill":"smuggler","wx":"fog"},{"id":"e2046","day":53,"season":2,"sday":23,"kind":"ambush","imp":3,"text":"Two Bog Crawlers come at the Scarlet Thorns' camp in Bleakmarsh in the middle of the night, and the Scarlet Thorns defeat them. The last bog crawler decides enough is enough, and goes. Ask anyone when it turned: Gorm's Deadfall. Tobias kept them off everyone with Ambush. Gorm fought with Ironroot the way her grandmother taught her. \"Thank you. All of you,\" says Gorm. Loot: 5 chitin.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f155","foes":["bog_crawler","bog_crawler"],"where":"at their camp in Bleakmarsh, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-59,"wx":"fog"},{"id":"e2095","day":54,"season":2,"sday":24,"kind":"ability","imp":2,"text":"Tobias decides the ford is too quiet and crosses half a mile upstream. From the far bank she can see the rope strung under the water at the usual crossing. Tobias walks on, calm as a Sunday.","heroes":["h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e2118","day":55,"season":2,"sday":25,"kind":"fight","imp":3,"text":"Tobias hits hardest as the Scarlet Thorns see off 2 Bog Crawlers in Bleakmarsh. Before Tobias' Thorn Whip it could have gone either way. Bramble Snare did more for this fight than the scoreboard shows. That was Gorm. Loot: 5 bog crawler claws, 3 chitin.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f161","foes":["bog_crawler","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"hero","reworded":-23},{"id":"e2143","day":56,"season":2,"sday":26,"kind":"fight","imp":2,"text":"Win number nine in a row: the Scarlet Thorns cut down 3 Risen Dead and a Will-o'-Wisp in Bleakmarsh. Tobias cleared two of them with a single Caltrops. Loot: 3 crypt-caps, 3 grave dust.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f163","foes":["zombie","zombie","wisp"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"streak","reworded":-26},{"id":"e2160","day":56,"season":2,"sday":26,"kind":"argument","imp":3,"text":"Gorm and Tobias are not speaking. It's about whose idea the last dungeon was. It's never really about whose idea the last dungeon was.","heroes":["h9","h6"],"parties":["p1"]},{"id":"e2175","day":57,"season":2,"sday":27,"kind":"road","imp":3,"text":"Tobias finds an abandoned caravan beside the road to Ashfen, wheels sunk, wagons empty save for a chest wedged under a seat with 11 silver in it.","heroes":["h6","h9"],"parties":["p1"],"road":"ashfen~bleakmarsh","road_rec":"r372"},{"id":"e2184","day":57,"season":2,"sday":27,"kind":"campfire","imp":2,"text":"Tobias keeps Gorm alive with one well-timed spell. Gorm buys the drinks for a week.","heroes":["h9","h6"],"parties":["p1"],"loc":"ashfen"},{"id":"e2212","day":58,"season":2,"sday":28,"kind":"meet","imp":2,"text":"The Green Arrows and The Scarlet Thorns share a fire in Bleakmarsh. Fenwick shares directions.","heroes":["h17","h13","h6","h9"],"parties":["p5","p1"],"loc":"bleakmarsh"},{"id":"e2215","day":58,"season":2,"sday":28,"kind":"talent","imp":1,"text":"Tobias plays a pedlar for his boots at a roadside halt, wins them, and gives them back. Mostly.","heroes":["h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"card_sharp"},{"id":"e2237","day":59,"season":2,"sday":29,"kind":"fight","imp":1,"text":"The Scarlet Thorns cut down Risen Dead in Bleakmarsh, in thick fog. Tobias closed it out with Thorn Whip on the risen dead. Loot: 3 crypt-caps.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f170","foes":["zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"weather","reworded":-14,"wx":"fog"},{"id":"e2238","day":59,"season":2,"sday":29,"kind":"fight","imp":1,"text":"The Scarlet Thorns, in fine spirits lately, cut down Risen Dead in Bleakmarsh. Tobias' Poisoned Blade put poison in the risen dead, and it did its slow work. The others will say it was close. Gorm made sure it wasn't.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f171","foes":["zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"fog"},{"id":"e2241","day":59,"season":2,"sday":29,"kind":"night","imp":2,"text":"A hooded stranger shares The Scarlet Thorns' fire in Bleakmarsh, eats half the stew, and says something very specific about the Wolf Den before leaving.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2252","day":59,"season":2,"sday":29,"kind":"argument","imp":1,"text":"Tobias says one thing too many about the party's name. Gorm says two.","heroes":["h6","h9"],"parties":["p1"]},{"id":"e2267","day":60,"season":2,"sday":30,"kind":"fight","imp":2,"text":"The Scarlet Thorns meet 2 Risen Dead in Bleakmarsh and see them off. The risen dead was already dying of Tobias' Thorn Whip before it knew it. Gorm kept them off everyone with Bramble Snare. Loot: 4 grave dust, 3 remains.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f173","foes":["zombie","zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-14,"wx":"fog"},{"id":"e2269","day":60,"season":2,"sday":30,"kind":"fight","imp":1,"text":"In Bleakmarsh, the Scarlet Thorns square up to Risen Dead and carry the day. Tobias' Thorn Whip put poison in the risen dead, and it did its slow work. Tobias kept them off everyone with Ambush. Loot: 3 grave dust.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f174","foes":["zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-25,"wx":"fog"},{"id":"e2285","day":60,"season":2,"sday":30,"kind":"ability","imp":2,"text":"A broken twig, a gate left open, a farm dog that won't bark: Tobias reads all three and goes round. Nothing at all happens on the road today, which was the idea.","heroes":["h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"true_pathfinder","sk":"True Pathfinder","rule":true,"wx":"fog"},{"id":"e2372","day":62,"season":3,"sday":2,"kind":"road","imp":3,"text":"Tobias walks a lost child along the road to Redcrag Hills all the way to a village, where a whole street turns out to cheer. A farmer gives her a loaf.","heroes":["h6","h9"],"parties":["p1"],"road":"ironhaven~redcrag","road_rec":"r413"},{"id":"e2389","day":63,"season":3,"sday":3,"kind":"fight","imp":1,"text":"A Bandit falls to the Scarlet Thorns in Redcrag Hills. The final blow was Gorm's Deadfall. Loot: 8 silver each, 1 bag of stolen goods.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag","fight":"f176","foes":["bandit"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"foe","reworded":-2},{"id":"e2390","day":63,"season":3,"sday":3,"kind":"fight","imp":2,"text":"Tobias hits hardest as the Scarlet Thorns make short work of a Cave Troll in Redcrag Hills. Everything after Tobias' Thorn Whip went right. Gorm was wherever the trouble was, every time. Loot: 9 silver each, 1 troll hide.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag","fight":"f177","foes":["cave_troll"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"hero","reworded":-23},{"id":"e2392","day":63,"season":3,"sday":3,"kind":"night","imp":2,"text":"Tobias's ghost story in Redcrag Hills goes on too long and never really ends. Gorm lies awake waiting for the ending.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag"},{"id":"e2412","day":63,"season":3,"sday":3,"kind":"meet","imp":1,"text":"Isolde and Tobias swap stories in Redcrag Hills while Juniper's Shields and The Scarlet Thorns swap rumours.","heroes":["h10","h12","h18","h6","h9"],"parties":["p4","p1"],"loc":"redcrag"},{"id":"e2416","day":63,"season":3,"sday":3,"kind":"campfire","imp":1,"text":"A wagon gets stuck on the road. Tobias and Gorm push it out together and refuse the farmer's coin.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag"},{"id":"e2432","day":64,"season":3,"sday":4,"kind":"fight","imp":1,"text":"In Redcrag Hills again, for the third time in two days: the Scarlet Thorns beat 2 Bandits. Before it's over, Tobias talks one bandit into putting the weapon down. The bandit moved like it was wading after Gorm's Bramble Snare. Tobias's Ambush kicked in when it counted. Loot: 8 silver each.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag","fight":"f185","foes":["bandit","bandit"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"again","reworded":-52},{"id":"e2441","day":64,"season":3,"sday":4,"kind":"ability","imp":2,"text":"Tobias stops at a quiet bend, frowns, and takes the long way. Later word comes of the bandits who waited there all day. The crew walks a little taller.","heroes":["h6"],"parties":["p1"],"loc":"redcrag","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e2453","day":65,"season":3,"sday":5,"kind":"fight","imp":1,"text":"The Scarlet Thorns, in fine spirits lately, beat a Kobold and a Giant Bat in Redcrag Hills. Tobias talks one kobold into walking away before it's over. Tobias' Thorn Whip put the giant bat down. Loot: a pair of bat wings.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag","fight":"f188","foes":["kobold","giant_bat"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"mood","reworded":-26},{"id":"e2500","day":66,"season":3,"sday":6,"kind":"gift","imp":2,"text":"Tobias admired Gorm's Medal of Baked Crust one too many times. Now it's Tobias's.","heroes":["h9","h6"],"parties":["p1"],"loc":"ironhaven"},{"id":"e2504","day":66,"season":3,"sday":6,"kind":"talent","imp":1,"text":"Gorm talks hops with an Ironhaven grower and argues weather for twenty minutes. Both enjoy it. That's Brewer for you.","heroes":["h9"],"parties":["p1"],"loc":"ironhaven","skill":"brewer"},{"id":"e2506","day":66,"season":3,"sday":6,"kind":"argument","imp":2,"text":"Gorm and Tobias spend supper disagreeing about whether the last fight was a retreat or a 'tactical repositioning', politely at first.","heroes":["h9","h6"],"parties":["p1"]},{"id":"e2527","day":67,"season":3,"sday":7,"kind":"party_life","imp":3,"text":"Gorm asks Tobias if the view is nice up there. It is.","heroes":["h6","h9"],"parties":["p1"],"loc":"ironhaven","wx":"rain"},{"id":"e2570","day":68,"season":3,"sday":8,"kind":"fight","imp":1,"text":"On the King's Road, the Scarlet Thorns square up to a Bandit Archer and carry the day. Tobias' last Thorn Whip settled it. Without Tobias's Ambush, this goes differently. Loot: 8 silver each.","heroes":["h6","h9"],"parties":["p1"],"loc":"kingsroad","fight":"f200","foes":["bandit_archer"],"where":"in The King's Road","won":true,"close":false,"shape":"place","reworded":-13},{"id":"e2576","day":68,"season":3,"sday":8,"kind":"ability","imp":2,"text":"Tobias spots fresh boot-prints off the road, says nothing, and quietly picks another route. Gorm only works it out at supper, and sleeps better for it.","heroes":["h6","h9"],"parties":["p1"],"loc":"kingsroad","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e2595","day":69,"season":3,"sday":9,"kind":"fight","imp":2,"text":"The Scarlet Thorns see off 2 Bandit Archers and a Bandit Captain on the King's Road without much fuss. Tobias talks one bandit captain into walking away before it's over. The fight turned on Tobias' Thorn Whip. Bramble Snare did more for this fight than the scoreboard shows. That was Gorm. Loot: 9 silver each, 1 bag of stolen goods.","heroes":["h6","h9"],"parties":["p1"],"loc":"kingsroad","fight":"f202","foes":["bandit_archer","bandit_captain","bandit_archer"],"where":"in The King's Road","won":true,"close":false,"shape":"plain","reworded":-19},{"id":"e2625","day":70,"season":3,"sday":10,"kind":"road","imp":3,"text":"Tobias takes a mail bag on from the Wheel and Whistle for a rider who has gone lame, and the clerk at the far end pays 11 silver for its delivery.","heroes":["h6","h9"],"parties":["p1"],"road":"carrbridge~kingsroad","road_rec":"r467"},{"id":"e2648","day":71,"season":3,"sday":11,"kind":"road","imp":4,"text":"Captain Mabb asks, very formally, whether the Fourth-Best Company might join Tobias as hirelings. Tobias says no, kindly. They take it well and buy the mule a hat.","heroes":["h6","h9"],"parties":["p1"],"road":"ashfen~carrbridge","traveller":"fourth_best","road_rec":"r472"},{"id":"e2661","day":71,"season":3,"sday":11,"kind":"argument","imp":1,"text":"The Scarlet Thorns spend the evening listening to Tobias and Gorm argue about whether ghosts can be bribed.","heroes":["h6","h9"],"parties":["p1"]},{"id":"e2669","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Scarlet Thorns settle on a goal: to see the world: 6 different places before the season ends.","heroes":["h6","h9"],"parties":["p1"]},{"id":"e2714","day":73,"season":3,"sday":13,"kind":"ability","imp":2,"text":"Bandits wait in the ditch on the road to Ironhaven. One of them leans on a stick that Gorm put there. A net drops, a bell rings, and the ambush is over.","heroes":["h9"],"parties":["p1"],"loc":"ironhaven","skill":"every_path_rigged","sk":"Every Path Rigged","rule":true},{"id":"e2732","day":73,"season":3,"sday":13,"kind":"campfire","imp":2,"text":"Tobias stands in front of Gorm when the arrows start. Gorm notices.","heroes":["h6","h9"],"parties":["p1"],"loc":"ironhaven"},{"id":"e2768","day":74,"season":3,"sday":14,"kind":"ability","imp":1,"text":"Tobias reads the crows circling over the next wood, says 'not today', and turns aside. Whatever was waiting in there waits for somebody else, and the party sleeps easy.","heroes":["h6"],"parties":["p1"],"loc":"redcrag","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e2771","day":74,"season":3,"sday":14,"kind":"argument","imp":3,"text":"Tobias and Gorm spend supper disagreeing about who ate the last of the cheese, politely at first.","heroes":["h6","h9"],"parties":["p1"]},{"id":"e2775","day":74,"season":3,"sday":14,"kind":"goal_progress","imp":2,"text":"The Scarlet Thorns are getting close: see the world: 6 different places before the season ends (4 of 6 places).","heroes":["h6","h9"],"parties":["p1"]},{"id":"e2790","day":75,"season":3,"sday":15,"kind":"fight","imp":2,"text":"Tobias hits hardest as the Scarlet Thorns make short work of 2 Drakes in Redcrag Hills. Tobias talks one drake out of the fight before it's over. Tobias' Poisoned Blade put poison in the drake, and it did its slow work. Loot: 3 drake scales, 5 fangs & claws, 3 drake flanks.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag","fight":"f216","foes":["drake","drake"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"hero","reworded":-23},{"id":"e2791","day":75,"season":3,"sday":15,"kind":"talent","imp":2,"text":"Gorm lights the campfire by breathing on it. Tobias has seen this forty times and still claps. One quiet Fire Eater, and done.","heroes":["h9","h6"],"parties":["p1"],"loc":"redcrag","skill":"fire_eater"},{"id":"e2835","day":76,"season":3,"sday":16,"kind":"skim","imp":2,"text":"Tobias quietly pockets an extra 16 silver while The Scarlet Thorns count the rest. Nobody notices.","heroes":["h6"],"parties":["p1"],"loc":"redcrag","in_fight":"f217","wx":"storm"},{"id":"e2836","day":76,"season":3,"sday":16,"kind":"fight","imp":2,"text":"It's 2 Cave Trolls and a Giant Bat against the Scarlet Thorns in Redcrag Hills, and it isn't close. Tobias talks one cave troll out of the fight before it's over. Frost from Gorm's Bramble Snare had the cave troll stumbling. Loot: 8 silver each, 1 troll hide.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag","fight":"f217","foes":["cave_troll","giant_bat","cave_troll"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"foe","reworded":-26,"wx":"storm"},{"id":"e2854","day":77,"season":3,"sday":17,"kind":"fight","imp":1,"text":"The Scarlet Thorns, in fine spirits lately, dispatch a Kobold in Redcrag Hills. Tobias' last Thorn Whip settled it. Loot: 1 silver each.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag","fight":"f218","foes":["kobold"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"storm"},{"id":"e2887","day":78,"season":3,"sday":18,"kind":"party_life","imp":1,"text":"By the third crossroads Tobias has stopped waiting and started complaining about the wait.","heroes":["h6","h9"],"parties":["p1"],"loc":"redcrag"},{"id":"e2888","day":78,"season":3,"sday":18,"kind":"road","imp":3,"text":"Sir Aldous Puddle proudly shows Gorm the tally on the bridge board. Gorm is surprised to find it very close.","heroes":["h9","h6"],"parties":["p1"],"road":"ironhaven~redcrag","traveller":"aldous","road_rec":"r522"},{"id":"e2892","day":78,"season":3,"sday":18,"kind":"wagon","imp":3,"text":"The Scarlet Thorns roll out of Ironhaven in an ox wagon called The Ark, 64 silver between them. Tobias paid for all of it.","heroes":["h6","h9"],"parties":["p1"],"loc":"ironhaven"},{"id":"e2977","day":80,"season":3,"sday":20,"kind":"talent","imp":2,"text":"Gorm circles the camp at dusk with a coil of wire. Tobias learns to step high on the way to bed. Every Path Rigged, the guild calls it.","heroes":["h9","h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"every_path_rigged"},{"id":"e2992","day":80,"season":3,"sday":20,"kind":"ability","imp":2,"text":"Tobias decides the ford is too quiet and crosses half a mile upstream. From the far bank she can see the rope strung under the water at the usual crossing. Tobias walks on, calm as a Sunday.","heroes":["h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e2996","day":80,"season":3,"sday":20,"kind":"campfire","imp":2,"text":"Tobias walks the dark side of the road so Gorm doesn't have to, and never says why.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh"},{"id":"e3025","day":81,"season":3,"sday":21,"kind":"fight","imp":1,"text":"In Bleakmarsh, Risen Dead gets in the Scarlet Thorns' way, briefly. It was even until Tobias' Thorn Whip. Then it wasn't. Loot: 3 grave dust, 4 crypt-caps.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f228","foes":["zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-16},{"id":"e3028","day":81,"season":3,"sday":21,"kind":"talent","imp":1,"text":"Gorm blazes the trees round camp so the next crew through can find the water. Good manners on the road.","heroes":["h9"],"parties":["p1"],"loc":"bleakmarsh","skill":"trailblazer"},{"id":"e3029","day":81,"season":3,"sday":21,"kind":"night","imp":1,"text":"Tobias follows strange lights away from the camp in Bleakmarsh, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh"},{"id":"e3035","day":81,"season":3,"sday":21,"kind":"campfire","imp":1,"text":"Tobias and Gorm find a pear tree by the road and eat far more than is wise.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh"},{"id":"e3072","day":82,"season":3,"sday":22,"kind":"fight","imp":2,"text":"The Scarlet Thorns meet 2 Bog Crawlers and 2 Giant Spiders in Bleakmarsh and cut them down. Tobias talks one bog crawler into walking away before it's over. Gorm's Deadfall caught four of them at once. Loot: 10 chitin, 3 bog crawler claws, 1 trinket.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh","fight":"f232","foes":["bog_crawler","giant_spider","giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-15},{"id":"e3074","day":82,"season":3,"sday":22,"kind":"night","imp":1,"text":"Someone leaves a scrap of map by The Scarlet Thorns' fire in Bleakmarsh in the night. It shows a door in the Ashveil Crypts that isn't on any other map.","heroes":["h6","h9"],"parties":["p1"],"loc":"bleakmarsh"},{"id":"e3082","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Gorm rebuilds a stile that's been broken for years. A farmer watches, nods, and drops off a ham. Every snaremaster learns Carpentry sooner or later. Not every snaremaster learns it like that.","heroes":["h9"],"parties":["p1"],"loc":"bleakmarsh","skill":"carpenter"},{"id":"e3086","day":82,"season":3,"sday":22,"kind":"argument","imp":2,"text":"It starts with the ethics of looting bodies. It ends with Gorm and Tobias sleeping on opposite sides of the fire.","heroes":["h9","h6"],"parties":["p1"]},{"id":"e3088","day":82,"season":3,"sday":22,"kind":"campfire","imp":1,"text":"Duke the dog has chosen Tobias. Tobias pretends to mind. Gorm is quietly delighted.","heroes":["h9","h6"],"parties":["p1"],"loc":"bleakmarsh"},{"id":"e3164","day":84,"season":3,"sday":24,"kind":"road","imp":3,"text":"Captain Dorrit Salt teaches Gorm six sailor's knots on the verge, and one that is, she says, not for polite company.","heroes":["h9","h6"],"parties":["p1"],"road":"ashfen~bleakmarsh","traveller":"salt","road_rec":"r578"},{"id":"e3165","day":84,"season":3,"sday":24,"kind":"talent","imp":1,"text":"Tobias checks for anthills before anyone sits. Two crews ago, this would have mattered a lot.","heroes":["h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"campsite_scout"},{"id":"e3176","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Tobias makes tea the slow way: warm the pot, count to sixty, pour. The crew stops bickering to watch. Tea Ceremony: one of the things Tobias learned the long way round.","heroes":["h6"],"parties":["p1"],"loc":"thornmere_ruins","skill":"tea_ceremony"},{"id":"e3192","day":85,"season":3,"sday":25,"kind":"argument","imp":1,"text":"The Scarlet Thorns spend the evening listening to Gorm and Tobias argue about whose idea the last dungeon was.","heroes":["h9","h6"],"parties":["p1"]},{"id":"e3197","day":85,"season":3,"sday":25,"kind":"goal_done","imp":4,"text":"GOAL: The Scarlet Thorns set out to see the world: 6 different places before the season ends, and they have done it, with 5 days to spare. XP: Tobias +960 (level 20!), Gorm +960 (level 20!).","heroes":["h6","h9"],"parties":["p1"],"xp":{"h6":960,"h9":960}},{"id":"e3204","day":86,"season":3,"sday":26,"kind":"delve","imp":1,"text":"The Scarlet Thorns descend into Thornmere Ruins, mostly unexplored (31%).","heroes":["h6","h9"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e3205","day":86,"season":3,"sday":26,"kind":"fight","imp":2,"text":"Tobias hits hardest as the Scarlet Thorns cut down 2 Bog Crawlers and 2 Will-o'-Wisps in the drowned nave on floor 2 of Thornmere Ruins. Before it's over, Tobias talks one bog crawler into putting the weapon down. Tobias' Shadow of Death landed on the will-o'-wisp at the right moment. Gorm's Snare Field turned the fight. Loot: 5 bottled wisplight, 5 chitin.","heroes":["h6","h9"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f239","foes":["bog_crawler","wisp","wisp"],"where":"in the drowned nave on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-36},{"id":"e3206","day":86,"season":3,"sday":26,"kind":"gear","imp":4,"text":"Gorm carries a tall lantern with a flame that leans towards the door from the Lantern That Waits up out of Thornmere Ruins wrapped in a cloak. It hums. Someone in town will have to say why.","heroes":["h6","h9"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e3207","day":86,"season":3,"sday":26,"kind":"famous_trap","imp":4,"text":"Gorm beats The Lantern That Waits in Thornmere Ruins, the first to do it since the new tenant moved in. They'll be telling this one for weeks.","heroes":["h6","h9"],"parties":["p1"],"loc":"thornmere_ruins"},{"id":"e3208","day":86,"season":3,"sday":26,"kind":"delve_day","imp":1,"text":"The Scarlet Thorns work floor 2 of Thornmere Ruins at a push pace: 3 rooms (the drowned nave, The Lantern That Waits, the flooded side aisle).","heroes":["h6","h9"],"parties":["p1"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"size":2,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["unique"],"fears":1,"wild":[]}},{"id":"e3252","day":87,"season":3,"sday":27,"kind":"delve_day","imp":1,"text":"The Scarlet Thorns work floor 2 of Thornmere Ruins at a steady pace: 2 rooms (the reliquary niche, the pipe organ).","heroes":["h6","h9"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e3253","day":87,"season":3,"sday":27,"kind":"talent","imp":1,"text":"Gorm wakes to find Tobias already on watch. Gorm never saw her get up.","heroes":["h6","h9"],"parties":["p1"],"loc":"thornmere_ruins","skill":"shadow_of_death"},{"id":"e3278","day":87,"season":3,"sday":27,"kind":"talent","imp":1,"text":"Gorm names every star over the camp by which road it hangs above. Walker of All Roads, the guild calls it.","heroes":["h9"],"parties":["p1"],"loc":"thornmere_ruins","skill":"walker_of_all_roads"},{"id":"e3290","day":88,"season":3,"sday":28,"kind":"fight","imp":2,"text":"It's 3 Bog Crawlers and a Siren against the Scarlet Thorns in the pond banks on floor 2 of Thornmere Ruins, and it isn't close. Before it's over, Tobias talks one siren into putting the weapon down. Ask anyone when it turned: Gorm's Deadfall. Loot: 5 bog crawler claws, 3 chitin.","heroes":["h6","h9"],"parties":["p1"],"loc":"thornmere_ruins","fight":"f252","foes":["siren","bog_crawler","bog_crawler"],"where":"in the pond banks on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-39},{"id":"e3291","day":88,"season":3,"sday":28,"kind":"delve_day","imp":1,"text":"The Scarlet Thorns work floor 2 of Thornmere Ruins at a steady pace: 3 rooms (the font that still fills, the pond banks, the cloister walk).","heroes":["h6","h9"],"parties":["p1"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"size":2,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":1,"wild":[]}},{"id":"e3310","day":88,"season":3,"sday":28,"kind":"talent","imp":1,"text":"Tobias picks a campsite with a view, a stream and no mosquitoes. Nobody knows how.","heroes":["h6"],"parties":["p1"],"loc":"thornmere_ruins","skill":"true_pathfinder"},{"id":"e3327","day":89,"season":3,"sday":29,"kind":"delve_done","imp":3,"text":"Thornmere Ruins gives up The Scarlet Thorns after 4 days, a little reluctantly, like a cat letting go of a sock. They got down to floor 2, cleared 8 rooms, inked 12% of the map, disarmed 2 traps, came across The Lantern That Waits, the pipe organ and the pond banks, came away with 26 silver between them and turned back because they were down to the last torch. The guild's map has it: Thornmere Ruins is partly explored (44%).","heroes":["h6","h9"],"parties":["p1"],"loc":"thornmere_ruins","days":4,"bottom":false,"rooms":["The Lantern That Waits","the pipe organ"],"gold":26,"turn":"dark"},{"id":"e3365","day":90,"season":3,"sday":30,"kind":"ability","imp":2,"text":"Tobias hears a bridge creak wrong, walks the long way round, and is proven right by a loud splash behind her. It is not her splash.","heroes":["h6"],"parties":["p1"],"loc":"bleakmarsh","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e3383","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Scarlet Thorns, never to leave a companion behind (sworn in season 2); Sunlit Quills, that no one leaves this party (sworn in season 2); The Thunder of Frosthold, to die rich (sworn in season 2); The Tidal Ledger, to keep the peace: never draw first on another hero (sworn in season 2); Ash, to keep the peace: never draw first on another hero (sworn in season 1); Fenwick, never to pay a toll (sworn in season 1). Every one of them held.","heroes":["h12","h17"],"parties":["p1","p2","p3","p7"]}],"roles":{"h6":"Tracker","h9":"Leader · Quartermaster"},"quest":{"what":"Head home","where":"Ashfen","why":"heading home to Ashfen","floor":null,"floors":null},"tactics":{"front":[],"back":["h6","h9"],"plan":"Tobias and Gorm pick off whatever gets close.","traits":{"boldness":0.01,"risk":-0.19,"greed":-0.21,"sociability":0.16,"honor":0.35,"curiosity":0.0,"temper":-0.28,"loyalty":0.06},"mix":"2 bows","notes":["Nobody wants the front row. Whoever's nearest takes the hits.","No healer: every wound comes home with them."],"style":["skirmishers"],"skills":[{"label":"Damage","skills":[{"hero":"h6","id":"thorn_whip","name":"Thorn Whip","desc":"A vine with ideas.","tags":["nature"],"rank":2,"uses":44},{"hero":"h6","id":"caltrops","name":"Caltrops","desc":"A handful of spikes, scattered where feet go.","tags":["craft","stealth"],"rank":2,"uses":27},{"hero":"h6","id":"poisoned_blade","name":"Poisoned Blade","desc":"A smear of something green along the edge.","tags":["stealth"],"rank":1,"uses":23},{"hero":"h9","id":"deadfall","name":"Deadfall","desc":"A log, a rope, and a very bad afternoon for goblins.","tags":["nature","craft"],"rank":2,"uses":16}]},{"label":"Tricks","skills":[{"hero":"h6","id":"ambush","name":"Ambush","desc":"The party always strikes first.","tags":["stealth","nature"],"rank":2,"uses":42},{"hero":"h9","id":"bramble_snare","name":"Bramble Snare","desc":"Brambles, plaited into something that holds.","tags":["nature","craft"],"rank":1,"uses":16},{"hero":"h6","id":"pay_them_off","name":"Pay Them Off","desc":"Throws a purse. One of them picks it up and goes home.","tags":["trade"],"rank":1,"uses":8},{"hero":"h9","id":"snare_field","name":"Snare Field","desc":"Half the enemy finds the snares. The other half finds out.","tags":["nature","craft"],"rank":1,"uses":7},{"hero":"h6","id":"camouflage","name":"Camouflage","desc":"Becomes a bush. A suspicious bush.","tags":["stealth","nature"],"rank":2,"uses":6},{"hero":"h6","id":"shadow_of_death","name":"Shadow of Death","desc":"Nobody hears them. Nobody needs to.","tags":[],"rank":1,"uses":3},{"hero":"h9","id":"camouflage","name":"Camouflage","desc":"Becomes a bush. A suspicious bush.","tags":["stealth","nature"],"rank":2,"uses":2}]},{"label":"Always on","skills":[{"hero":"h6","id":"evasive","name":"Evasive","desc":"Hard to pin down.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h9","id":"honed_edge","name":"Honed Edge","desc":"Sharpened every night, without fail.","tags":["craft"],"rank":3,"uses":0}]},{"label":"On the road","skills":[{"hero":"h6","id":"drillmaster","name":"Drillmaster","desc":"Drills the crew at dawn. The crew hates it. The crew is better.","tags":["command"],"rank":1,"uses":0},{"hero":"h6","id":"campsite_scout","name":"Campsite Scout","desc":"Finds the flat spot. Every time.","tags":["travel","nature"],"rank":1,"uses":0},{"hero":"h6","id":"forager","name":"Forager","desc":"Finds dinner and herbs on any trail.","tags":["nature"],"rank":1,"uses":0},{"hero":"h6","id":"whetstone","name":"Whetstone","desc":"Sharpens everything. Has been asked to stop.","tags":["craft"],"rank":1,"uses":0},{"hero":"h6","id":"herbalism","name":"Herbalism","desc":"Knows every useful leaf.","tags":["nature","heal"],"rank":1,"uses":0},{"hero":"h6","id":"smuggler","name":"Smuggler","desc":"Knows every false bottom in every cart.","tags":["trade","stealth"],"rank":1,"uses":0},{"hero":"h6","id":"card_sharp","name":"Card Sharp","desc":"The deck is always friendlier in their hands.","tags":[],"rank":1,"uses":0},{"hero":"h6","id":"smokehouse","name":"Smokehouse","desc":"Smoked fish, smoked sausage, smoked everything.","tags":[],"rank":1,"uses":0},{"hero":"h6","id":"tea_ceremony","name":"Tea Ceremony","desc":"Nothing is so bad it can't wait for the kettle.","tags":[],"rank":1,"uses":0},{"hero":"h9","id":"hedge_wizard","name":"Hedge Wizardry","desc":"Fixes kettles with spells and spells with kettles.","tags":["arcane","craft"],"rank":2,"uses":0},{"hero":"h9","id":"tin_can_line","name":"Tin-Can Line","desc":"Cans on a string round the camp. Nothing sneaks up. Nobody sleeps.","tags":["nature","craft"],"rank":2,"uses":0},{"hero":"h9","id":"carpenter","name":"Carpentry","desc":"Measures twice, cuts once, builds a bench.","tags":["craft"],"rank":2,"uses":0},{"hero":"h9","id":"mushroom_hunter","name":"Mushroom Hunter","desc":"Knows which ones are dinner and which ones are a funeral.","tags":[],"rank":1,"uses":0},{"hero":"h9","id":"campsite_scout","name":"Campsite Scout","desc":"Finds the flat spot. Every time.","tags":["travel","nature"],"rank":1,"uses":0},{"hero":"h9","id":"trailblazer","name":"Trailblazer","desc":"Cuts a day off long roads.","tags":["travel"],"rank":1,"uses":0},{"hero":"h9","id":"spelunker","name":"Spelunker","desc":"Happiest in a crack the width of a loaf.","tags":["travel","stealth"],"rank":1,"uses":0},{"hero":"h9","id":"brewer","name":"Brewer","desc":"Every camp has a bubbling pot that isn't soup.","tags":[],"rank":1,"uses":0},{"hero":"h9","id":"fire_eater","name":"Fire Eater","desc":"Eats fire. Never orders hot soup.","tags":[],"rank":1,"uses":0}]}],"share":[{"hero":"h6","dmg":1788,"healed":0,"taken":162,"kills":13,"row":"back"},{"hero":"h9","dmg":1097,"healed":0,"taken":281,"kills":6,"row":"back"}],"ground":{"name":"Bleakmarsh","fights":20}},"trophies":[]};